class BellekRepository:
    def __init__(self, stok):
        self.stok = stok

    def yeterli_mi(self, adet):
        return adet > 0 and self.stok >= adet

    def azalt(self, adet):
        self.stok -= adet


class IndirimStrategy:
    def __init__(self, oran):
        self.oran = oran

    def indirimli(self, tutar):
        return tutar * (100 - self.oran) // 100


